contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string[] calldata modelURIs,
        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public {
        // Precondition: no winners have been picked yet in this fresh deployment.
        require(c.roundId() == 0);

        uint32 before = c.numRoundsClaimed(address(this));

        // State-changing call as its own top-level statement.
        c.claimRewards(modelURIs, modelTypes, customAttributes);

        uint32 after_ = c.numRoundsClaimed(address(this));

        // General rule: with zero completed rounds, claiming succeeds and
        // does not advance the caller's claim counter.
        assert(c.roundId() == 0 && before == 0 && after_ == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 points) public {
        // Precondition: caller (this test contract) is not the ranked battle contract.
        require(address(this) != c._rankedBattleAddress() || true);

        uint256 beforePoints = c.fighterPoints(tokenId);
        uint256 beforeTotal = c.totalPoints();

        bool reverted;
        try c.addPoints(tokenId, points) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPoints = c.fighterPoints(tokenId);
        uint256 afterTotal = c.totalPoints();

        assert(reverted && beforePoints == afterPoints && beforeTotal == afterTotal);
    }

    receive() external payable {}
}

