contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newWinnersPerPeriod, uint256[] calldata wrongLenWinners, uint256[] calldata rightLenWinners) public {
        // give the test contract (deployer/admin of c) a chosen winners-per-period
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        assert(c.winnersPerPeriod() == newWinnersPerPeriod);

        // a correctly-sized array still reverts because this contract is not the admin of c?
        // it IS admin (constructor sets isAdmin[_ownerAddress], owner is deployer), so it must NOT revert,
        // but ownerOf on the fighter farm (a stub) would revert -> wrap in try/catch and require revert flag
        bool reverted;
        uint256 beforeRound = c.roundId();
        uint256 beforeWpp = c.winnersPerPeriod();

        // wrong-length call must revert
        try c.pickWinner(wrongLenWinners) { reverted = false; } catch { reverted = true; }
        require(reverted, "wrong length must revert");
        require(c.roundId() == beforeRound, "roundId changed on failed pick");
        require(c.winnersPerPeriod() == beforeWpp, "wpp changed on failed pick");
        require(!c.isSelectionComplete(beforeRound), "selection complete on failed pick");

        assert(reverted && c.roundId() == beforeRound && c.winnersPerPeriod() == beforeWpp && !c.isSelectionComplete(beforeRound));
    }

    receive() external payable {}
}

