contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod());
        uint256 roundBefore = c.roundId();
        // Non-admin pickWinner attempt: adjust admin access off then back on.
        c.adjustAdminAccess(address(this), false);
        bool revertedNonAdmin;
        try c.pickWinner(winners) { revertedNonAdmin = false; } catch { revertedNonAdmin = true; }
        c.adjustAdminAccess(address(this), true);
        // Admin pickWinner succeeds.
        c.pickWinner(winners);
        bool complete = c.isSelectionComplete(roundBefore);
        uint256 roundAfter = c.roundId();
        // Duplicate pickWinner on the same round reverts.
        bool revertedDup;
        try c.pickWinner(winners) { revertedDup = false; } catch { revertedDup = true; }
        assert(
            revertedNonAdmin &&
            !complete == false &&
            complete &&
            roundAfter == roundBefore + 1 &&
            revertedDup &&
            c.isSelectionComplete(roundBefore)
        );
    }
    receive() external payable {}
}

