        bool postReverted;
        try c.updateWinnersPerPeriod(newValue + 1) { postReverted = false; } catch { postReverted = true; }

        assert(
            !preReverted &&
            postReverted &&
            c.winnersPerPeriod() == winnersBefore &&
            !c.isAdmin(address(this))
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners) public payable {
        uint256 wpp = c.winnersPerPeriod();
        require(winners.length == wpp, "length must equal winnersPerPeriod");

        // Make the test contract an admin (it is the contract owner deployed by the checker).
        c.adjustAdminAccess(address(this), true);

        uint256 roundBefore = c.roundId();
        bool completeBefore = c.isSelectionComplete(roundBefore);

        // pick winner for the current round
        c.pickWinner(winners);

        // read resulting state through the public surface
        bool completeAfter = c.isSelectionComplete(roundBefore);
        bool completeNewRound = c.isSelectionComplete(roundBefore + 1);
        uint256 roundAfter = c.roundId();

        // winnerAddresses[roundBefore] must equal the input winners
        bool allMatch = true;
        for (uint256 i = 0; i < winners.length; i++) {
            if (c.winnerAddresses(roundBefore, i) != c.ownerOf(winners[i])) {
                allMatch = false;
            }
            if (c.fighterPoints(winners[i]) != 0) {
                allMatch = false;
            }
        }

        assert(
            completeBefore == false &&
            completeAfter == true &&
            completeNewRound == false &&
            roundAfter == roundBefore + 1 &&
            allMatch
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners) public payable {
        uint256 wpp = c.winnersPerPeriod();
        require(winners.length == wpp, "length must equal winnersPerPeriod");

        // The test contract becomes an admin so it can pick winners.
        c.adjustAdminAccess(address(this), true);

        uint256 roundBefore = c.roundId();
        bool completeBefore = c.isSelectionComplete(roundBefore);

        // Points of picked tokens before the call.
        uint256 len = winners.length;
        uint256[] memory pointsBefore = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            pointsBefore[i] = c.fighterPoints(winners[i]);
        }

        // pickWinner for the current round
        c.pickWinner(winners);

        // Read resulting state through the public surface
        bool completeAfter = c.isSelectionComplete(roundBefore);
        bool completeNewRound = c.isSelectionComplete(roundBefore + 1);
        uint256 roundAfter = c.roundId();
        uint256 winnersLenStored = c.winnerAddresses(roundBefore, 0) != address(0) || len == 0 ? len : 0;

        // Each picked token's points must now be zero
        bool allZero = true;
        for (uint256 i = 0; i < len; i++) {
            if (c.fighterPoints(winners[i]) != 0) {
                allZero = false;
            }
        }

        assert(
            completeBefore == false &&
            completeAfter == true &&
            completeNewRound == false &&
            roundAfter == roundBefore + 1 &&
            winnersLenStored == len &&
            allZero
        );
    }

    receive() external payable {}
}

