        string[] calldata modelTypes,
        uint256[2][] calldata customAttributes
    ) public payable {
        // With no claimable rewards, the arrays must be empty (nothing can be minted).
        require(modelURIs.length == 0, "no models expected");
        require(modelTypes.length == 0, "no model types expected");
