        uint256 pointsAfter = c.fighterPoints(tokenId);
        uint256 totalAfter = c.totalPoints();
        assert(pointsAfter == pointsBefore + p1 + p2 && totalAfter == totalBefore + p1 + p2);
    }
    receive() external payable {}
}

